text:
 {
  "turns": [
    {
      "speaker": "agent",
      "text": "Thank you for calling Nimbus Telecom. My name is Sana. How can I help you today?",
      "tags": [
        "greeting"
      ]
    },
    {
      "speaker": "customer",
      "text": "I am beyond frustrated! My phone has been dropping calls every five minutes and the screen is flickering constantly. This is ridiculous!",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I need your account number and date of birth to access your records.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "My account number is 44083287 and my date of birth is 16/01/1996. My name is Michael Iyer.",
      "tags": [
        "identity_verification"
      ]
    },
    {
      "speaker": "agent",
      "text": "The account is verified. What is the phone number associated with the account?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "It is 94562 38486.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I am checking the network status in your area. There are no reported outages, so the issue is likely with your device or the SIM card.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "I don't care whose fault it is, I just want it to work! I've been trying to fix this for hours.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I will send a replacement SIM card to your address on file.",
      "tags": [
        "action:device_fix"
      ]
    },
    {
      "speaker": "customer",
      "text": "Okay, that handles the SIM, but what about the network drops and the flickering screen?",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I am raising a network ticket to investigate the signal strength at your location.",
      "tags": [
        "action:technician_or_ticket"
      ]
    },
    {
      "speaker": "customer",
      "text": "Thank you so much, Sana. I really appreciate you getting this sorted for me.",
      "tags": []
    }
  ]
}
